style.css:
/* Target Edgenuity player page */
@-moz-document domain("r13.core.learn.edgenuity.com") {
/* Set the background image */
    body {
        background-image: url("https://i.pinimg.com/736x/93/f5/1c/93f51cbc3fc6d948312a29115b092f4d.jpg") !important;
        background-size: cover !important; /* Ensure it covers the screen */
        background-repeat: no-repeat !important; /* Prevent repeating */
        background-position: center !important; /* Center the image */
        color: white !important; /* White text color */
    }

    /* Change text color for headings and paragraphs to white */
    h1, h2, h3, h4, h5, h6, p, span, div, a {
        color: white !important; /* White text */
    }

    /* Change button and UI elements styles to pink */
    button, input[type="button"], input[type="submit"], .btn {
        background-color: #FFB6C1 !important; /* Pink background for buttons */
        color: white !important; /* White text on buttons */
        border: none !important;
        font-weight: bold;
        padding: 10px 20px;
        border-radius: 5px;
    }

    /* Change button color on hover */
    button:hover, input[type="button"]:hover, input[type="submit"]:hover, .btn:hover {
        background-color: #FF80A3 !important; /* Slightly darker pink on hover */
    }

    /* Optional: Adjust header if needed */
    .header {
        background-color: rgba(255, 255, 255, 0.8) !important; /* Light overlay to make text readable */
    }

    /* Change color of links to white */
    a {
        color: white !important;
        text-decoration: none;
    }

    /* Optional: Add hover effect for links */
    a:hover {
        color: #FFB6C1 !important; /* Light pink on hover */
    }
    
    /* Optional: Style the input fields to have a pink background */
    input[type="text"], input[type="password"], textarea {
        background-color: #FFB6C1 !important;
        color: white !important;
        border: 1px solid white !important;
        border-radius: 5px;
    }
}
